    transformations = set()
    length = len(word_core)

    # Deletion
    for i in range(length):
        transformations.add(word_core[:i] + word_core[i+1:])

    # Insertion
    for i in range(length + 1):
        for char in 'abcdefghijklmnopqrstuvwxyz':
            transformations.add(word_core[:i] + char + word_core[i:])

