    for i, word in enumerate(cores):
        similar_words[word] = set()
        for j, other in enumerate(cores):
            if i != j and are_similar(word, other):
                similar_words[word].add(other)
        if similar_words[word]:
            similar_words[word] = sorted(similar_words[word])
    return similar_words

def are_similar(word1, word2):
    if len(word1) == len(word2):
        # Check for one replacement
        return sum(c1 != c2 for c1, c2 in zip(word1, word2)) == 1
    elif len(word1) + 1 == len(word2):
        # Check for one insertion
        for i in range(len(word2)):
            if word1 == word2[:i] + word2[i+1:]:
                return True
    elif len(word1) - 1 == len(word2):
        # Check for one deletion
        for i in range(len(word1)):
            if word1[:i] + word1[i+1:] == word2:
                return True
    elif len(word1) == len(word2) - 1:
        # Check for one insertion in word2 (which is a deletion in word1)
        return are_similar(word2, word1)
    return False

