import sys
from collections import defaultdict

def core(word):
    return ''.join(c.lower() for c in word if c.isalpha())

def generate_neighbors(core_word):
    neighbors = set()
    alphabet = 'abcdefghijklmnopqrstuvwxyz'

    for i in range(len(core_word)):
        # Deletion
        neighbors.add(core_word[:i] + core_word[i+1:])

        # Replacement
        for char in alphabet:
            neighbors.add(core_word[:i] + char + core_word[i+1:])

    # Insertion
    for i in range(len(core_word) + 1):
        for char in alphabet:
            neighbors.add(core_word[:i] + char + core_word[i:])

    # Transposition
    for i in range(len(core_word) - 1):
        neighbors.add(core_word[:i] + core_word[i+1] + core_word[i] + core_word[i+2:])

    return neighbors

def typo_checker(text):
    word_dict = defaultdict(set)
    words = text.split()

    for word in words:
        word_core = core(word)
        if word_core:
            word_dict[word_core].add(word)

    similar_words = defaultdict(set)

    for core_word in word_dict.keys():
        neighbors = generate_neighbors(core_word)
        for neighbor in neighbors:
            if neighbor in word_dict and neighbor != core_word:
                similar_words[core_word].update(word_dict[neighbor])

